import { PasswordHasherService, PasswordVerificationResult } from './password-hasher.service';

describe('PasswordHasherService', () => {
  const hasher = new PasswordHasherService();

  // Generated by the real Microsoft.AspNetCore.Identity.PasswordHasher<TUser> via
  // tools/PasswordHashCheck for "TestPassword123!" — proves byte-for-byte format parity.
  const dotnetHash = 'AQAAAAEAACcQAAAAECBxucbFkzHTNTZIuONHK+yeafN9+jUS8Zs0Cd8KGbbzKmFqRsyQ3n6oYw4l1asajg==';

  it('verifies a real .NET-generated V3 hash with the correct password', () => {
    expect(hasher.verifyHashedPassword(dotnetHash, 'TestPassword123!')).toBe(PasswordVerificationResult.Success);
  });

  it('rejects a real .NET-generated V3 hash with the wrong password', () => {
    expect(hasher.verifyHashedPassword(dotnetHash, 'WrongPassword')).toBe(PasswordVerificationResult.Failed);
  });

  it('round-trips its own hashPassword output', () => {
    const hash = hasher.hashPassword('AnotherPassword!42');
    expect(hasher.verifyHashedPassword(hash, 'AnotherPassword!42')).toBe(PasswordVerificationResult.Success);
    expect(hasher.verifyHashedPassword(hash, 'nope')).toBe(PasswordVerificationResult.Failed);
  });

  it('verifies a legacy V2 (ASP.NET Identity 2.x) hash and flags it for rehash', () => {
    // Hand-built V2 hash: marker 0x00 + 16-byte salt + PBKDF2-SHA1(1000 iters, 32 bytes).
    const { pbkdf2Sync, randomBytes } = require('crypto');
    const salt = randomBytes(16);
    const subkey = pbkdf2Sync('LegacyPass1', salt, 1000, 32, 'sha1');
    const v2Hash = Buffer.concat([Buffer.from([0x00]), salt, subkey]).toString('base64');

    expect(hasher.verifyHashedPassword(v2Hash, 'LegacyPass1')).toBe(PasswordVerificationResult.SuccessRehashNeeded);
  });
});
